import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import type { Objective } from '@/entities/objective/types'
import { Star } from 'lucide-react'
import { useAuth } from '@/app/providers/AuthProvider'
import { evaluationsService } from '@/integrations/supabase/evaluations'

type Props = { objective: Objective }

export function EvaluateTab({ objective }: Props) {
  const { user } = useAuth()
  const qc = useQueryClient()
  const [rating, setRating] = useState(0)
  const [feedback, setFeedback] = useState('')

  const { data: evaluations = [] } = useQuery({
    queryKey: ['evaluations', objective.id],
    queryFn: () => evaluationsService.listForObjective(objective.id),
  })

  const submitMut = useMutation({
    mutationFn: () => evaluationsService.submit({
      objectiveId: objective.id,
      evaluatorId: user!.id,
      evaluatorName: user?.displayName ?? 'You',
      rating,
      feedback: feedback || undefined,
    }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['evaluations', objective.id] })
      setRating(0); setFeedback('')
      toast.success('Evaluation submitted')
    },
    onError: (e: Error) => toast.error(e.message),
  })

  const evaluators = objective.participants?.filter((p) => p.role === 'evaluator') ?? []

  return (
    <div className="p-6 max-w-2xl mx-auto">
      <div className="flex flex-col gap-4">
        {evaluations.map((ev) => (
          <div key={ev.id} className="bg-surface rounded-xl border border-border p-5">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <div className="h-7 w-7 rounded-full bg-accent/20 flex items-center justify-center text-xs font-medium text-accent">{ev.evaluatorName.charAt(0)}</div>
                <span className="text-sm font-medium">{ev.evaluatorName}</span>
              </div>
              <div className="flex gap-0.5">
                {[1,2,3,4,5].map((star) => <Star key={star} size={14} className={star <= ev.rating ? 'text-warning fill-warning' : 'text-border'} />)}
              </div>
            </div>
            {ev.feedback && <p className="text-sm text-muted-foreground bg-muted rounded-lg p-3">{ev.feedback}</p>}
          </div>
        ))}
        {evaluators.filter((e) => !evaluations.find((ev) => ev.evaluatorId === e.userId)).map((e) => (
          <div key={e.userId} className="bg-surface rounded-xl border border-dashed border-border p-5 text-center">
            <p className="text-sm text-muted-foreground">Waiting for evaluation from <strong>{e.displayName}</strong></p>
          </div>
        ))}
        <div className="bg-surface rounded-xl border border-border p-5">
          <h3 className="font-medium mb-4">Submit evaluation</h3>
          <div className="flex gap-1 mb-4">
            {[1,2,3,4,5].map((star) => (
              <button key={star} onClick={() => setRating(star)} className={star <= rating ? 'text-warning' : 'text-border hover:text-warning'}>
                <Star size={20} className={star <= rating ? 'fill-warning' : ''} />
              </button>
            ))}
          </div>
          <textarea value={feedback} onChange={(e) => setFeedback(e.target.value)} rows={4} placeholder="Provide feedback on the delivery..." className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent resize-none mb-3" />
          <button onClick={() => submitMut.mutate()} disabled={!rating || !user || submitMut.isPending} className="bg-accent text-accent-foreground px-4 py-2 rounded-lg text-sm hover:opacity-90 disabled:opacity-50">
            {submitMut.isPending ? 'Submitting…' : 'Submit evaluation'}
          </button>
        </div>
      </div>
    </div>
  )
}
